syntax:
returnType functionName(parameterList)   // function header
{
    // function body: statements that do the job
    return value;   // sends a value back (not needed in a void function)
}

int main()
{
    functionName(arguments);   // function call: runs the function
    return 0;
}

sample.code:
#include <iostream>
using namespace std;

void sayHello() {
    cout << "Hello from a function!" << endl;
}

int main() {
    cout << "Start" << endl;
    sayHello();
    cout << "End" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int add(int x, int y) {
    return x + y;
}

int main() {
    int a = 7, b = 5;
    int s = add(a, b);
    cout << "Sum = " << s << endl;
    cout << "Another sum = " << add(100, 250) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int larger(int a, int b) {
    if (a > b) {
        return a;
    }
    return b;
}

int main() {
    int p, q;
    cin >> p >> q;
    cout << "Larger = " << larger(p, q) << endl;
    return 0;
}

